import json, os
from http.server import BaseHTTPRequestHandler, HTTPServer

BOOKINGS = []

class Handler(BaseHTTPRequestHandler):
    def _send(self, code, body, kind='application/json'):
        data = body if isinstance(body, bytes) else json.dumps(body).encode()
        self.send_response(code)
        self.send_header('Content-Type', kind)
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path == '/healthz':
            return self._send(200, {'ok': True})
        if self.path == '/api/bookings':
            return self._send(200, BOOKINGS)
        name = 'index.html' if self.path in ('/', '') else self.path.lstrip('/')
        path = os.path.join(os.path.dirname(__file__), 'public', name)
        if not os.path.isfile(path):
            return self._send(404, {'error': 'not found'})
        kind = 'text/html' if name.endswith('.html') else 'application/javascript'
        with open(path, 'rb') as f:
            return self._send(200, f.read(), kind)

    def do_POST(self):
        if self.path != '/api/bookings':
            return self._send(404, {'error': 'not found'})
        length = int(self.headers.get('Content-Length', 0))
        BOOKINGS.append(json.loads(self.rfile.read(length) or b'{}'))
        return self._send(201, BOOKINGS[-1])

if __name__ == '__main__':
    HTTPServer(('0.0.0.0', int(os.environ.get('PORT', '8080'))), Handler).serve_forever()

