const list = document.getElementById('list');
async function load() {
  const items = await (await fetch('api/bookings')).json();
  list.innerHTML = items.map(b => `<li>${b.name}</li>`).join('');
}
document.getElementById('book').onsubmit = async (e) => {
  e.preventDefault();
  await fetch('api/bookings', {method: 'POST', body: JSON.stringify({name: e.target.name.value})});
  e.target.reset();
  load();
};
load();
